"use client"
import { useQuery } from "@tanstack/react-query"
import { useState } from "react"
import { Button } from "@/shared/components/ui/button"
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card"
import { departamentsApi, Envelope } from "@/entities/departaments/api"
import { DepartamentChild, DepartamenthAndChildDto } from "@/entities/departaments/types"

const PAGE_SIZE = 4

export default function Locam() {
  const [page, setPage] = useState(1)

  const { data, isLoading, error } = useQuery<Envelope<DepartamenthAndChildDto>, Error>({
    queryKey: ["departaments", page],
    queryFn: () =>
      departamentsApi.getDepartaments({
        page,
        pageSize: PAGE_SIZE,
        prefetch: 3,
      }),
  })

  const models: DepartamentChild[] = data?.result?.departamenthAndChildModels ?? []
  const total = data?.result?.totalCount ?? 0
  const lastPage = Math.max(1, Math.ceil(total / PAGE_SIZE))

  return (
    <div className="p-6 md:p-8 min-h-screen bg-background text-foreground">
      <div className="mb-6 flex flex-col gap-1">
        <p className="text-xs uppercase tracking-[0.2em] text-muted-foreground">Локации / Департаменты</p>
        <h1 className="text-3xl font-bold">Департаменты</h1>
        <p className="text-sm text-muted-foreground max-w-2xl">
          Здесь отображаются департаменты и их метаданные. Используйте пагинацию для просмотра всех корневых элементов.
        </p>
      </div>

      {isLoading ? (
        <div className="rounded-xl border border-border bg-card p-6">
          <div className="h-4 w-2/5 animate-pulse rounded bg-muted" />
          <div className="mt-3 h-3 w-1/3 animate-pulse rounded bg-muted" />
          <div className="mt-2 h-3 w-1/4 animate-pulse rounded bg-muted" />
        </div>
      ) : error ? (
        <div className="rounded-xl border border-destructive/40 bg-destructive/10 p-4 text-destructive">
          Ошибка при загрузке департаментов. Попробуйте обновить страницу.
        </div>
      ) : models.length === 0 ? (
        <div className="rounded-xl border border-border bg-card p-6 text-muted-foreground">
          Департаменты не найдены.
        </div>
      ) : (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {models.map((item) => (
            <Card key={item.id} className="border border-border/70 bg-white/80 dark:bg-slate-900/70">
              <CardHeader>
                <div className="flex items-start justify-between gap-3">
                  <div>
                    <CardTitle className="text-lg">{item.name}</CardTitle>
                    <CardDescription>
                      <span className="font-medium">ID:</span> {item.identifier}
                    </CardDescription>
                  </div>
                  <span
                    className={`rounded-full px-2 py-1 text-[11px] font-semibold ${
                      item.isActive ? "bg-emerald-100 text-emerald-700" : "bg-slate-200 text-slate-600"
                    }`}
                  >
                    {item.isActive ? "Активен" : "Неактивен"}
                  </span>
                </div>
              </CardHeader>
              <CardContent>
                <div className="space-y-2 text-sm text-muted-foreground">
                  <div>
                    <span className="font-semibold text-foreground">Глубина:</span> {item.depth}
                  </div>
                  <div>
                    <span className="font-semibold text-foreground">Путь:</span> {item.path}
                  </div>
                  <div>
                    <span className="font-semibold text-foreground">Родитель:</span> {item.parentId ?? "—"}
                  </div>
                  <div>
                    <span className="font-semibold text-foreground">Дочерних:</span> {item.childs?.length ?? 0}
                  </div>
                </div>
                {item.childs?.length ? (
                  <div className="mt-3 rounded-md border border-border/70 bg-muted p-2 text-xs text-muted-foreground">
                    <div className="mb-1 font-semibold text-foreground">Дочерние департаменты:</div>
                    <ul className="list-disc pl-4">
                      {item.childs.slice(0, 3).map((child) => (
                        <li key={child.id} className="truncate">
                          {child.name}
                        </li>
                      ))}
                      {item.childs.length > 3 && <li>+ {item.childs.length - 3} ещё...</li>}
                    </ul>
                  </div>
                ) : null}
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      <div className="mt-6 flex flex-wrap items-center gap-2">
        <Button
          variant="outline"
          size="sm"
          onClick={() => setPage((prev) => Math.max(1, prev - 1))}
          disabled={page <= 1 || isLoading}
        >
          ← Назад
        </Button>
        <Button
          variant="outline"
          size="sm"
          onClick={() => setPage((prev) => Math.min(lastPage, prev + 1))}
          disabled={page >= lastPage || isLoading}
        >
          Далее →
        </Button>
        <div className="ml-auto text-sm text-muted-foreground">
          Страница {page} из {lastPage} • Всего {total}
        </div>
      </div>
    </div>
  )
}
